INSERT INTO `editions_edition` VALUES (1,'Montevideo Fant├ístico XV',15,2024,'xv','2024-09-21','2024-10-10','past',0,'archive/XV/poster.jpg','','','','','','','','','','2026-04-14 22:36:18.057748','2026-04-18 00:41:50.543992','{\"jury\": [{\"members\": [\"Valentina Starcovich\", \"Pablo Silvera\", \"Enrique Puig\"], \"section\": \"Competencia Oficial de Largometrajes\"}, {\"members\": [\"Valentina Starcovich\", \"comit├⌐ de preselecci├│n del festival\"], \"section\": \"Competencia Iberoamericana de Largometrajes\"}, {\"members\": [\"Gabriel Llagostera\", \"Andr├⌐s D\'Souza\", \"Federico Cardozo\"], \"section\": \"Mediometrajes\"}, {\"members\": [\"Pablo Saldivia\", \"Tom├ís Martos\", \"Mat├¡as Parkman\"], \"section\": \"Cortos Uruguayos\"}, {\"members\": [\"Victoria Soto\", \"Bruno Otheguy\", \"Andr├⌐s Larramendi\"], \"section\": \"Cortos Internacionales\"}], \"awards\": [{\"jury\": \"Victoria Soto, Bruno Otheguy, Andr├⌐s Larramendi\", \"awards\": [{\"film\": \"La Tumba de San Or├ín\", \"name\": \"Menci├│n Especial del Jurado ΓÇö Mejor corto animado\", \"country\": \"Australia\"}, {\"film\": \"Musa\", \"name\": \"Menci├│n Especial del Jurado ΓÇö Direcci├│n de fotograf├¡a\", \"country\": \"M├⌐xico\"}, {\"film\": \"En las sombras\", \"name\": \"Menci├│n Especial del Jurado ΓÇö Puesta en escena\", \"country\": \"Francia\"}, {\"film\": \"El sue├▒o de Pinky\", \"name\": \"Mejor gui├│n\", \"country\": \"EEUU\"}, {\"film\": \"Belfast 1912\", \"name\": \"Mejor Actor\", \"country\": \"Reino Unido\", \"recipient\": \"Stephen Beggs\"}, {\"film\": \"Asustada\", \"name\": \"Mejor Actriz\", \"country\": \"Argentina\", \"recipient\": \"Gaia Garibaldi Arg├╝ello\"}, {\"film\": \"Encarnaci├│n\", \"name\": \"Mejor Director\", \"country\": \"Jap├│n\", \"recipient\": \"Noboru Suzuki\"}, {\"film\": \"R├¡o de caracoles\", \"name\": \"Mejor Corto Iberoamericano\", \"country\": \"Colombia\"}, {\"film\": \"Lo que no nos decimos\", \"name\": \"Mejor Cortometraje del Festival\", \"country\": \"Espa├▒a\"}], \"section\": \"Cortos Internacionales\"}, {\"jury\": \"Gabriel Llagostera, Andr├⌐s D\'Souza y Federico Cardozo\", \"awards\": [{\"film\": \"Lola contra los zombies\", \"name\": \"Menci├│n Especial del Jurado ΓÇö Mejor Fotograf├¡a\", \"country\": \"Argentina\"}, {\"film\": \"Debacle\", \"name\": \"Menci├│n Especial del Jurado ΓÇö Mejor Puesta en Escena\", \"country\": \"M├⌐xico\"}, {\"film\": \"La Piedra Roja\", \"name\": \"Mejor Mediometraje\", \"country\": \"M├⌐xico\"}], \"section\": \"Mediometrajes\"}, {\"jury\": \"Valentina Starcovich y comit├⌐ de preselecci├│n del festival\", \"awards\": [{\"film\": \"El S├│tano\", \"name\": \"Mejor Largometraje Iberoamericano\"}], \"section\": \"Competencia Iberoamericana de Largometrajes\"}, {\"jury\": \"Valentina Starcovich, Pablo Silvera y Enrique Puig\", \"awards\": [{\"film\": \"Hippo\", \"name\": \"Menci├│n Especial del Jurado ΓÇö Mejor Actriz de Reparto\", \"recipient\": \"Eliza Roberts\"}, {\"film\": \"Fuera de Camino\", \"name\": \"Menci├│n Especial del Jurado ΓÇö Mejor Estilismo y maquillaje\"}, {\"film\": \"Hippo\", \"name\": \"Mejor Guion\", \"recipient\": \"Kimball Farley y Mark H. Rapaport\"}, {\"film\": \"Hippo\", \"name\": \"Mejor Actor\", \"recipient\": \"Kim Farley\"}, {\"film\": \"Crookedfinger\", \"name\": \"Mejor Actriz\", \"recipient\": \"Paula Jon Derose\"}, {\"film\": \"La Espera\", \"name\": \"Mejor Director\", \"recipient\": \"Fernando J. Guti├⌐rrez\"}, {\"film\": \"Hippo\", \"name\": \"Mejor Pel├¡cula\"}], \"section\": \"Competencia Oficial de Largometrajes\"}], \"edition\": {\"year\": 2024, \"dates\": \"21 de setiembre ΓÇö 10 de octubre de 2024\", \"roman\": \"XV\", \"title\": \"Montevideo Fant├ístico XV\", \"number\": 15, \"poster\": \"/media/archive/XV/poster.jpg\", \"venues\": []}, \"sections\": [{\"name\": \"Competencia Oficial de Largometrajes\", \"type\": \"features\", \"films\": [{\"cast\": \"Paula Jon DeRose, Welker White, Blake DeLong, Andrea Lyman, Jos├⌐ Guns Alves\", \"slug\": \"crookedfinger\", \"year\": 2024, \"title\": \"Crookedfinger\", \"poster\": \"\", \"country\": \"Estados Unidos\", \"director\": \"Jason Cortlund, Julia Halperin\", \"duration\": 91, \"synopsis\": \"Tras la repentina muerte de sus ancianos padres, Mar├¡a Gallucci regresa a la casa de su infancia en Cape Cod (Massachusetts). Cuando el hermano de Mar├¡a, Nico (y su novia mayor, Sigrid) aparecen para ayudar a arreglar la herencia, pronto aumentan las tensiones sobre cu├íl es la mejor manera de vender la decr├⌐pita casa. Mientras Mar├¡a y Sigrid forjan una amistad inesperada, la volatilidad emocional de Nico se vuelve cada vez m├ís inestable. ┬┐Ser├í el efecto de una antigua lesi├│n cerebral, el costo de revivir traumas familiares pasados o algo relacionado con el extra├▒o zumbido vibrante que s├│lo Mar├¡a parece o├¡r en esa casa? Interesante thriller sobrenatural que indaga principalmente en la psicolog├¡a de la protagonista, no tanto en lo que respecta a las extra├▒as sensaciones que le transmite la casa de sus padres fallecidos, sino m├ís bien al miedo al aislamiento, a estar completamente sola dentro de una cada vez m├ís compleja situaci├│n familiar.\"}, {\"cast\": \"Julia Dorothee Brunsch, Isabelle von Stauffenberg, Dolores Winkler, Tania Golden, Robert Herzl\", \"slug\": \"bernadette-quiere-matarse\", \"year\": 2024, \"title\": \"Bernadette quiere matarse\", \"poster\": \"\", \"country\": \"Suiza\", \"director\": \"Robert Herzl, Oliver Paulus\", \"duration\": 92, \"synopsis\": \"En las oscuras profundidades de la red, Bernadette se une al enigm├ítico d├║o de influencers Kitty y Peter para orquestar la desaparici├│n de la estudiante Lotte: una transmisi├│n en vivo destinada a dejar a Internet en efervescencia. Sin embargo, Bernadette imagin├│ todo esto de manera muy diferenteΓÇª Comedia terror├¡fica que ironiza sobre usuarios de redes y plataformas que comparten pr├ícticamente todo en l├¡nea. En el caso de esta producci├│n suiza, el abordaje pisa el acelerador y se mete a fondo en la exploraci├│n de personajes, sin concesiones ni tampoco perdiendo de vista el eje de un asunto tan llamativo como preocupante, y m├ís all├í de los giros en la historia.\"}, {\"cast\": \"Lena Sch├╢nleitner, Christian Sch├╢nleitner, Sonja Hecherberger, Barbara Ziller, Severin Sch├╢nleitner\", \"slug\": \"entra-en-mycel\", \"year\": 2023, \"title\": \"Entra en Mycel\", \"poster\": \"\", \"country\": \"Austria\", \"director\": \"Daniel Limmer\", \"duration\": 74, \"synopsis\": \"Lena, de trece a├▒os, debe cuidar a su hermana peque├▒a tras la muerte de su madre, mientras su padre lucha por superar la p├⌐rdida. Al mismo tiempo, un extra├▒o par├ísito f├║ngico conocido como Mycel se est├í extendiendo y est├í transformando el mundo que rodea a Lena. Drama de ciencia ficci├│n austr├¡aco, hecho con apenas 3.000 euros y entre 8 personas, dirigido por el joven Daniel Limmer, aqu├¡ en su ├│pera prima, una distop├¡a que parte de una p├⌐rdida familiar y se extiende, como el par├ísito del t├¡tulo original, a un apocalipsis donde el f├¡sico y hasta los pensamientos de los humanos son tomados como parte de un todo. En ese contexto hay una gran apuesta audiovisual, creativa, por cierto, lindando con lo experimental, con momentos realmente intensos, y tambi├⌐n reminiscencias de la oniricidad de David Lynch y el horror corporal de David Cronenberg.\"}, {\"cast\": \"Irina Salikova, Sergey Gilev, Alex├⌐i Yarmilko, Dmitry Moiseev, Andrey Artamonov\", \"slug\": \"encuentros\", \"year\": 2023, \"title\": \"Encuentros\", \"poster\": \"\", \"country\": \"Rusia\", \"director\": \"Dmitry Moiseev\", \"duration\": 101, \"synopsis\": \"La ex enfermera Nina, que cuida de un alien├¡gena d├⌐bil, comienza a oponerse a un grupo de funcionarios corruptos que est├í intimidando al extraterrestre y extrayendo una sustancia valiosa de ├⌐l. Cuando se pone en contacto con el alien├¡gena, Nina comprende la verdad sobre dichos seres y la invasi├│n a la Tierra, lo que cambia por completo su vida. Sorprendente ├│pera prima de Dmitry Moiseev, que desde el inicio de la pel├¡cula plantea un contexto donde los extraterrestres ya son parte de la sociedad rusa, la cual los vio venir por primera vez en los a├▒os 80, durante la era sovi├⌐tica, y que siguen presentes con sus misteriosas naves y prop├│sitos hasta el d├¡a de hoy. Los lugares tradicionales y cierta esencia en la pel├¡cula remite al mejor cine de Tarkovskii (Solaris, Stalker, El sacrificio), aunque el mensaje que se pretende transmitir es mucho m├ís sencillo, directo y frontal. Toda una revelaci├│n dentro del festival.\"}, {\"cast\": \"V├¡ctor Clavijo, Ruth D├¡az, Mois├⌐s Ruiz, Manuel Mor├│n, Pedro Casablanc\", \"slug\": \"la-espera\", \"year\": 2023, \"title\": \"La Espera\", \"poster\": \"\", \"country\": \"Espa├▒a\", \"director\": \"F. Javier Guti├⌐rrez\", \"duration\": 103, \"synopsis\": \"Eladio, un guarda de una finca de caza, acepta un soborno de un cazador veterano. Lo que parec├¡a la oportunidad de su vida se convierte en un macabro descenso al infierno. Drama rural cuyo terror folkl├│rico, ambientado en la Espa├▒a de la d├⌐cada del 70, intenta explorar a fondo la naturaleza humana, sobre la premisa de una conocida referencia b├¡blica y que deriva en situaciones impactantes, siempre dentro de una atm├│sfera cada vez m├ís perturbadora y que parece no tener fin. Javier Guti├⌐rrez es uno de los m├ís aclamados directores de cine independiente espa├▒ol, incluso admirado por destacados cineastas de Estados Unidos y Jap├│n.\"}, {\"cast\": \"Jon Oswald, Scott Turner Schofield, Ashley Smith, Reed Diamond, Jared Bankens\", \"slug\": \"fuera-de-camino\", \"year\": 2022, \"title\": \"Fuera de Camino\", \"poster\": \"\", \"country\": \"Estados Unidos\", \"director\": \"Nathan Tape\", \"duration\": 91, \"synopsis\": \"Dos amigos vuelven a reunirse luego de que uno de ellos, que sue├▒a con vender su demo de rap, pasara un a├▒o en la c├írcel por una estupidez. Para celebrar la salida de prisi├│n, ambos se embarcan en un viaje de ida al ├║nico lugar en la Tierra donde saben que se sienten aceptados. En el camino, se equivocan de ruta y terminan en un contexto jam├ís imaginado, por los bosques del sur de Estados Unidos. Se cruzan con un sheriff psic├│tico, pandilleros, una princesa de un parque de casas rodantes, y un polic├¡a bueno que vive alucinando. Ser├¡a algo as├¡ como ver personajes de Terry Gilliam y David Lynch metidos en una pel├¡cula de los hermanos Coen, pero detr├ís de todo lo loco y delirante que pueda haber en esta ├│pera prima de Nathan Tape (quien trabajara para el director Kevin Smith), va irrumpiendo un drama con momentos inspirad├¡simos.\"}, {\"cast\": \"Kimball Farley, Lilla Kizlinger, Eliza Roberts, Jesse Pimentel, Eric Roberts\", \"slug\": \"hippo\", \"year\": 2023, \"title\": \"Hippo\", \"poster\": \"\", \"country\": \"Estados Unidos\", \"director\": \"Mark H. Rapaport\", \"duration\": 101, \"synopsis\": \"La pel├¡cula examina el paso de dos hermanastros a la edad adulta: Hippo, un adolescente adicto a los videojuegos, y Buttercup, una inmigrante cat├│lica h├║ngara que ama la m├║sica cl├ísica y a Jes├║s. Al igual que la antigua Afrodita griega, el amor de Buttercup no es correspondido por un hermano que prefiere entregarse al arte de la guerra y el caos. El resultado es una pesadilla tragic├│mica y cargada de hormonas que hay que ver para creer. Ambientada a fines de los 90 en Estados Unidos y con personajes que lidian con diversos trastornos, esta ├│pera prima del joven Mark Rapaport est├í filmada enteramente en blanco y negro y no por casualidad parece que estuvi├⌐ramos viendo a Jim Jarmusch y uno de sus cl├ísicos.\"}, {\"cast\": \"Alan King, Christopher Kirby, Zoe Bertram, Greg Fleet, Bill Evans\", \"slug\": \"vincent\", \"year\": 2024, \"title\": \"Vincent\", \"poster\": \"\", \"country\": \"Australia\", \"director\": \"Alan King\", \"duration\": 92, \"synopsis\": \"El escritor Vincent Tremblay, que vive en una situaci├│n dif├¡cil, se escapa a un lugar apartado, decidido a terminar su primera novela. Sin embargo, su soledad dura poco, ya que una fuerza poderosa se manifiesta de repente y Vincent se encuentra atrapado en sus garras. Desafiante comedia negra, con toques fant├ísticos que quiz├ís puedan interpretarse, validarse desde la propia mente del espectador, al momento de discernir qu├⌐ es lo real y cu├ínto hay de ficci├│n en ese cambio radical que el protagonista le da a su vida. Esa narrativa algo experimental, no lineal y que remite bastante al Godard de la Nouvelle Vague, esa ambig├╝edad conceptual que maneja, encuentra en esta ├│pera prima del australiano Alan King uno de sus puntos m├ís ├ílgidos. Una de las sorpresas del festival que, sin dudas, hace de su director un cineasta a seguir. Premiada en Alemania.\"}]}, {\"name\": \"Competencia Iberoamericana de Largometrajes\", \"type\": \"features\", \"films\": [{\"cast\": \"Joaqu├¡n Gallardo, Maia Barrio, Ram├│n Caribe, Vic Cicuta, Eva Dans\", \"slug\": \"7-vidas\", \"year\": 2024, \"title\": \"7 vidas\", \"poster\": \"\", \"country\": \"Argentina\", \"director\": \"Alejo R├⌐bora\", \"duration\": 80, \"synopsis\": \"La c├│moda vida de Jorge en un edificio inteligente se desmorona cuando muere Ren├⌐, el gato al que debe cuidar a cambio de vivir en el apartamento. En ese momento, una mujer que dice ser la reencarnaci├│n del felino llega a su puerta y, alegando que fue v├¡ctima de un homicidio, lo arrastra a una carrera contrarreloj para intentar encontrar al asesino suelto. Mientras salen a la luz terribles secretos, la IA del edificio comienza a fallar, dej├índolos inmersos en una trampa mortal que los har├í explorar, en tono de comedia negra, la eventual amistad entre especies y, por qu├⌐ no, los v├¡nculos con otros entes inteligentes.\"}, {\"cast\": \"Magui Bravi, Eve Gasser, Mat├¡as Desiderio, Agust├¡n Olcese, Fernando Ni├▒o\", \"slug\": \"bloody-mary\", \"year\": 2024, \"title\": \"Bloody Mary\", \"poster\": \"\", \"country\": \"Argentina\", \"director\": \"Taz Pereyra\", \"duration\": 73, \"synopsis\": \"Moira y Letizia, dos brujas modernas con un oscuro secreto, realizan un ritual cada Luna de Sangre, en el que un hombre es un elemento crucial de su magia. Sin embargo, esta noche algo cambiar├í, el elegido amenaza con desentra├▒ar su plan orquestado. Con su poder y sus vidas en juego, Letizia y Moira deben enfrentarse a fuerzas imprevistas y a sus propios demonios internos. Sorprendentemente, el v├¡nculo entre ellas podr├¡a ser m├ís fuerte que cualquier hechizo, tal vez destinado a durar toda la eternidad. Decorosa propuesta de suspenso y misterio, con brujas y algunos di├ílogos graciosos de por medio. Ellas tienen el control y lo hacen saber a como d├⌐ lugar.\"}, {\"cast\": \"Carlos Buletich, Koko de Luxe, Vanesa Eme, Mar├¡a Bel├⌐n Klusener, Claudio Martin\", \"slug\": \"brujas-ellas-cruzaran-el-umbral\", \"year\": 2023, \"title\": \"Brujas: Ellas cruzar├ín el umbral\", \"poster\": \"\", \"country\": \"Argentina, Chile, Uruguay\", \"director\": \"D├⌐bora Araya, Gabriel D├¡az, Marcelo Fabani, Horacio Florent├¡n, Ruth G├│mez, Carlos Lasso\", \"duration\": 69, \"synopsis\": \"Un grupo de chicas que desea formar parte de una hermandad, tienen que contar historias de brujas para poder realizar un ritual y finalmente ser aceptadas. Sobre una idea original y bajo producci├│n de la argentina Ruth G├│mez, la pel├¡cula re├║ne varios directores y directoras (algunos/as que ya pasaron con sus cortos y largos por anteriores ediciones del Montevideo Fan) de cuatro pa├¡ses (Chile, M├⌐xico y Uruguay, adem├ís de Argentina). Terror que remite al cine cl├ísico, con algo de gore y goticismo, donde cada pa├¡s eligi├│ sus propias locaciones, formas de financiaci├│n (incluyendo crowfunding) y hasta filmaciones en plena cuarentena, haciendo hincapi├⌐ en leyendas aut├│ctonas y tem├íticas sociales a trav├⌐s de cinco historias y un hilo conductor.\"}, {\"cast\": \"Diego Montez, Yohan Levy, Analu Prestes, Cristina Pereira, Luisa Kozovski\", \"slug\": \"la-herencia\", \"year\": 2023, \"title\": \"La Herencia\", \"poster\": \"\", \"country\": \"Brasil\", \"director\": \"Jo├úo C├óndido Zacharias\", \"duration\": 80, \"synopsis\": \"Despu├⌐s de recibir noticias sobre la muerte de su madre, Thomas regresa a Brasil con su pareja, Beni. Una vez all├¡, se entera de una casa de campo que pertenece a una abuela a la que nunca conoci├│. Curiosos por reencontrarse con la historia de su familia, visitan la casa y Thomas es recibido por dos t├¡as mayores que lo tratan como a su hijo perdido hace mucho tiempo. A medida que Thomas se va enamorando cada vez m├ís del lugar, Beni comienza a sospechar que algo maligno se esconde bajo la fachada de una vida tranquila en el campo. El patrimonio al que hace referencia el t├¡tulo original, en esta ├│pera prima de Jo├úo C├óndido Zacharias, lleva a uno de los protagonistas a un descubrimiento impensado que lo har├í replantear varias cosas, en contraste consigo mismo y dentro de un contexto cada vez m├ís amenazante. El cine de terror brasilero sigue dando muestras interesantes en su etapa de renovaci├│n, aqu├¡ claramente marcado entre el terror cl├ísico y el moderno.\"}, {\"cast\": \"Magui Bravi, Roly Serrano, Facundo Salom├│n, Agust├¡n Olcese, Evelyn Gasser\", \"slug\": \"oro-negro\", \"year\": 2024, \"title\": \"Oro Negro\", \"poster\": \"\", \"country\": \"Argentina\", \"director\": \"Nicol├ís R├¡os\", \"duration\": 63, \"synopsis\": \"Ramiro se reencuentra con Dami├ín despu├⌐s de a├▒os sin verse. Dami├ín siempre tiene alg├║n asunto turbio en marcha. Esta vez quiere ir en busca de cierto tesoro escondido en un convento abandonado. Lara, la novia de Ramiro, no conf├¡a en Dami├ín y decide acompa├▒arlos. Lo que no saben es que llevarse ese objeto de all├¡ podr├¡a desatar una maldici├│n que los perseguir├í por siempre, a menos que lo devuelvan tal y como lo encontraron. Modesto y al mismo tiempo notable ejercicio terror├¡fico, din├ímico en su edici├│n (apenas tiene una hora de duraci├│n). Dentro de esa econom├¡a narrativa pasan muchas cosas que van y vienen a partir de un interrogatorio policial. Hay una historia que se nutre de terror expl├¡cito y sugesti├│n, de sorpresas y buenas interpretaciones.\"}, {\"cast\": \"Mario Mayo, Fabia Castro, Rut Santamar├¡a, Antonio Mayans, Lone Fleming\", \"slug\": \"os-reviento\", \"year\": 2023, \"title\": \"Os reviento\", \"poster\": \"\", \"country\": \"Espa├▒a\", \"director\": \"Kike Narcea\", \"duration\": 92, \"synopsis\": \"Nuthead finalmente est├í saliendo de la c├írcel, por lo que quiere convertirse en un buen ciudadano, llevando una vida tranquila junto a su perro. De repente, su padre muere y lo deja solo, lo que lleva a que en un corto per├¡odo de tiempo varios grupos de mafiosos y matones lleguen a la casa del protagonista (un exboxeador) con extra├▒as intenciones. ├ël tiene la misma voluntad para con todosΓÇª, aplastarlos. Una movida propuesta exploitation de acci├│n que por momentos no da respiro, con algo de comedia, dirigida por el tambi├⌐n dibujante de c├│mics, el espa├▒ol Kike Narcea. Cine clase B ambientado en una aldea, con una destacada actuaci├│n de su personaje principal (Mario Mayo) y una nost├ílgica y graciosa aparici├│n cerca del final. Premiada en Argentina, Canad├í, Espa├▒a, Estados Unidos y Rumania.\"}, {\"cast\": \"Clara Kovacic, Federico Venzi, Demian Salom├│n, Chucho Fern├índez, Pablo Pinto\", \"slug\": \"el-sotano\", \"year\": 2024, \"title\": \"El S├│tano\", \"poster\": \"\", \"country\": \"Argentina\", \"director\": \"Agustin Giagatanellis\", \"duration\": 75, \"synopsis\": \"Cuatro desconocidos se despiertan atados y heridos en un s├│tano. Ninguno de ellos sabe qu├⌐ est├í pasando. Un hombre enmascarado con un disfraz de conejo comienza a jugar con ellos y poco a poco va revelando sus secretos. Si bien la f├│rmula remite a una famosa saga de terror, muy reciente y exitosa, por cierto, el acertijo tiene un buen planteo; no se regodea en el gore y s├¡ trata de ser algo diferente, donde las actuaciones ayudan y mucho a darle un impulso extra a una historia cuya idea original es de una de las protagonistas y tambi├⌐n coguionista, Clara Kovacic. ├ôpera prima del director argentino Agust├¡n Giagatanellis.\"}, {\"cast\": \"Gast├│n Palermo, Clara Kovacic, Santiago Zapata, Nicol├ís Obreg├│n, Hilda Quipirolo\", \"slug\": \"el-ucumar\", \"year\": 2022, \"title\": \"El Ucumar\", \"poster\": \"\", \"country\": \"Argentina\", \"director\": \"Octavio Revol Molina\", \"duration\": 86, \"synopsis\": \"Un grupo de bi├│logos se encuentra en la selva norte├▒a argentina en busca de alguna evidencia de que all├¡ puede vivir el oso andino, el ├║nico ├║rsido sudamericano. En un bar se enteran de una leyenda aut├│ctona, la existencia de un supuesto hombre oso conocido como el Ucumar. Los habitantes del pueblo les contar├ín sus encuentros con la bestia. Inspirada en hechos reales y filmada en las provincias de Salta y C├│rdoba, la leyenda de la criatura del t├¡tulo aqu├¡ cobra vida a trav├⌐s de investigadores (uno totalmente esc├⌐ptico) y relatos de los pobladores del lugar. Es una ficci├│n y bastante bien equilibrada; el subg├⌐nero del Pie Grande y otras criaturas misteriosas va tomando un formato atractivo a trav├⌐s de reconstrucciones de hechos y en distintas ├⌐pocas, muy buenas filmaciones y trabajo de sonido.\"}, {\"cast\": \"Ant├│nio da Luz Louren├ºo Jorge, Jo├úo Loy, Marlon Fortes, Sara Fortes, Maria da Luz Lopes\", \"slug\": \"el-viejo-y-la-espada\", \"year\": 2024, \"title\": \"El Viejo y la Espada\", \"poster\": \"\", \"country\": \"Portugal\", \"director\": \"F├íbio Powers\", \"duration\": 64, \"synopsis\": \"De los bosques embrujados de un pueblo perdido portugu├⌐s nace una energ├¡a maligna que, sin temer a Dios ni al hombre, recorre los valles cosechando las almas de quienes se distraen con los placeres fugaces de lo inmediatoΓÇª Lo ├║nico que separa a estas entidades del apocalipsis final que esclavizar├í a la humanidad en el s├⌐ptimo c├¡rculo del infierno es un obrero de la construcci├│n jubilado, una botella de vino, una moto Z├╝ndapp de 50 cc y una espada pose├¡da por un extra├▒o demonio. Lo que en principio parec├¡a una t├¡pica comedia bizarra, una pel├¡cula clase Z hecha por y para los amigos, se va transformando, a trav├⌐s de su cada vez m├ís nutrido y casi permanente di├ílogo en un trabajo de terror, fantas├¡a y ciencia ficci├│n que tiene sus cosas para decir, en especial a trav├⌐s del personaje del t├¡tulo, y su espada, que se convierte en otro m├ís. Hecha apenas con 7.000 euros.\"}]}, {\"name\": \"Novedades\", \"type\": \"features\", \"films\": [{\"cast\": \"\", \"slug\": \"george-pal-un-marciano-de-hollywood-en-argentina\", \"year\": 2023, \"title\": \"George Pal: Un marciano de Hollywood en Argentina\", \"poster\": \"\", \"country\": \"Argentina\", \"director\": \"Ramiro San Honorio\", \"duration\": 75, \"synopsis\": \"Un documental que toma como eje central la figura del creador George Pal, desde sus comienzos, con un repaso din├ímico de su filmograf├¡a hasta sus datos menos conocidos de su pasado en Europa y su llegada a Hollywood. Un relato que reivindica al creador e impulsor de un sello ├║nico, de quien supo ser un faro para muchos realizadores contempor├íneos en el ├ímbito de la animaci├│n, el cine fant├ístico y la ciencia ficci├│n. La pieza documental nos presenta una narrativa extensa en testimonios de profesionales que indagan la obra de este realizador y productor. Interesant├¡simo documental del realizador, guionista y escritor Ramiro San Honorio, creativo en su estilo narrativo y no solo por su esp├¡ritu did├íctico (para las generaciones m├ís j├│venes que quiz├ís nunca vieron un trabajo de George Pal), sino tambi├⌐n por su car├ícter revelador.\"}, {\"cast\": \"Facundo Vrdoljak, Mari├íngeles Gagliano, Juan Ignacio Rodr├¡guez, Sof├¡a Soler, Juan Manuel Soto\", \"slug\": \"la-hacienda-el-regreso-de-los-malditos\", \"year\": 2024, \"title\": \"La Hacienda: El regreso de los malditos\", \"poster\": \"\", \"country\": \"Argentina\", \"director\": \"Gaby Smiths\", \"duration\": 67, \"synopsis\": \"Un grupo de amigos retorna a su ciudad natal despu├⌐s de muchos a├▒os. El viaje es una excusa para recordar viejos tiempos, pero se convierte en una pesadilla cuando desentierran sus recuerdos m├ís oscuros. El nuevo slasher del argentino Gaby Smiths, tambi├⌐n escrito por Mechi P├⌐rez, viene con una dosis de terror y violencia mucho m├ís mesurada que su ├│pera prima Los turistas (exhibida en la pasada edici├│n del festival) que brinda m├ís tiempo al desarrollo de la historia, a sus personajes, siempre con una impecable factura t├⌐cnica de por medio.\"}, {\"cast\": \"Nick Gaglia, Pradip Ahir, Kether Donohue, Kashi Baba, Nick Mancuso\", \"slug\": \"pinkcity-una-meditacion-psicodelica\", \"year\": 2024, \"title\": \"Pinkcity: Una meditaci├│n psicod├⌐lica\", \"poster\": \"\", \"country\": \"Estados Unidos\", \"director\": \"Nick Gaglia\", \"duration\": 96, \"synopsis\": \"Un occidental viaja por tierras extranjeras en busca de la mujer que ama, que se perdi├│ en el Ganges. Una experiencia psicod├⌐lica experimental/narrativa que se adentra en el coraz├│n de la India y en el alma humana. Del director Nick Gaglia ya se hab├¡a exhibido en el festival el thriller de misterio y ciencia ficci├│n Estados alterados de Plaine (2012). Aqu├¡ recurre al tema del abuso de adolescentes en cl├¡nicas de recuperaci├│n y por el cual se ha convertido en activista ampliamente reconocido. Su cine se planta ante verdades inc├│modas, y en el caso de Pink City con una actitud desafiante, frontal, profunda respecto a la actual sociedad occidental y al ser humano en s├¡.\"}, {\"cast\": \"Nida Wakim, Ra├»a Ha├»dar, Katy Younes, Omar Bakeer, Miran Malaeb\", \"slug\": \"zaman-dark\", \"year\": 2023, \"title\": \"Zaman Dark\", \"poster\": \"\", \"country\": \"L├¡bano\", \"director\": \"Christophe Karabache\", \"duration\": 93, \"synopsis\": \"El L├¡bano al borde del abismo. Khattar y Ana├»s, dos qu├¡micos despedidos, intentan un experimento ├║nico: sobrevivir aliment├índose de carne humana. Un d├¡a, la mujer desaparece, mientras el hombre se ve envuelto en una red de tr├ífico que implica exportar carne humana a cambio de importar armas de francotirador digitales de alta tecnolog├¡a. Del cineasta liban├⌐s (radicado en Francia) Christophe Karabache pudo verse en la edici├│n 12 del MF la premiada Vortex (2019); fiel a su peculiar estilo experimental, creativo, provocador, aqu├¡ pisa el acelerador a fondo con una propuesta m├ís radical, una distop├¡a que refleja la degradaci├│n del ser humano, en un contexto devastado, angustiante, con una crisis social y econ├│mica que afecta a sus habitantes en cuerpo y alma, y donde el cazador puede convertirse r├ípidamente en presa.\"}]}, {\"name\": \"Competencia Oficial Mediometrajes\", \"type\": \"features\", \"films\": [{\"cast\": \"Bruno Calderoni, Anand Quintero\", \"slug\": \"debacle\", \"year\": 2024, \"title\": \"Debacle\", \"poster\": \"\", \"country\": \"M├⌐xico\", \"director\": \"Nadia Islas Cital\", \"duration\": 29, \"synopsis\": \"Abaddon es un demonio que mata para ganarse la vida. Cuando aterroriza un pueblo del norte de M├⌐xico es humillado por sus habitantes, quienes son m├ís crueles y violentos que ├⌐l. Su ├║nica opci├│n para sobrevivir ser├í conservar su poder demon├¡aco.\"}, {\"cast\": \"Alejandro Araya, Dami├ín Bodenh├╢fer, Silvia Novak\", \"slug\": \"killswitch\", \"year\": 2024, \"title\": \"Killswitch\", \"poster\": \"\", \"country\": \"Chile\", \"director\": \"Luciano Pizanno\", \"duration\": 52, \"synopsis\": \"Sof├¡a se encuentra en terapia con su psiquiatra para recuperar sus recuerdos que han ido desapareciendo d├¡a a d├¡a desde hace un a├▒o. Luego de la sesi├│n regresa a su departamento, donde recibe una llamada de su novio con la propuesta de realizar un documental sobre una vieja leyenda urbana de ni├▒os vampiros en el Puerto de San Antonio, mientras ella coordina las entrevistas, comienza a recuperar su memoria a trav├⌐s de im├ígenes y sue├▒os que la llevan a cambiar su conducta.\"}, {\"cast\": \"Camila Vaccarini, Pedro Ontiveros, Melina Furgiuela\", \"slug\": \"lola-contra-los-zombies\", \"year\": 2024, \"title\": \"Lola contra los zombies\", \"poster\": \"\", \"country\": \"Argentina\", \"director\": \"Tom├ís Alberto R├¡os\", \"duration\": 24, \"synopsis\": \"Un virus zombie acecha Argentina. Una pareja, Lola y Vicente, se dirige en coche hacia una zona que promete ser segura. A 25 kms de la meta, el coche se aver├¡a y los deja varados en medio del campo. Lo que parec├¡a un problema deja de serlo cuando Vicente le revela a Lola que ha sido mordido y est├í a punto de convertirse en zombie, por lo que tendr├í que despedirse de ├⌐l y continuar sola.\"}, {\"cast\": \"Denisse Corona, Guadalupe Ortiz, Eduardo Andrade\", \"slug\": \"la-piedra-roja\", \"year\": 2024, \"title\": \"La Piedra Roja\", \"poster\": \"\", \"country\": \"M├⌐xico\", \"director\": \"Jaime Jasso\", \"duration\": 23, \"synopsis\": \"En Guadalajara, 1909, Carmen, una arque├│loga, regresa para investigar los hallazgos prehisp├ínicos enviados para el aniversario del D├¡a de la Independencia. En medio de la agitaci├│n pol├¡tica, se le encomienda la tarea de restaurar ciertos ├¡dolos y objetos, que se rumorea que est├ín malditos. Acompa├▒ada por Leonor, la ama de llaves, Carmen explora la casa monumental en busca de respuestas. Un espectro grotesco, compuesto de miembros humanos, acecha en las sombras mientras Carmen descubre un ├¡dolo prehisp├ínico especial. La casa se convierte en un escenario aterrador donde Carmen debe descifrar el misterio y sobrevivir a esta pesadilla.\"}, {\"cast\": \"Zazou De Cr├⌐cy, Thom Lef├¿vre, Ishtvan Nekrasov\", \"slug\": \"surfers-killers\", \"year\": 2024, \"title\": \"Surfers Killers\", \"poster\": \"\", \"country\": \"Francia\", \"director\": \"Olivier Wright\", \"duration\": 22, \"synopsis\": \"Cuando Sam y Alex, una pareja parisina en busca de emociones fuertes, van a acampar cerca de un remoto lugar para practicar surf en la costa oeste de Francia, se cruzan con dos surfistas rebeldes que pretenden hacerles pagar por invadir su playaΓÇª\"}, {\"cast\": \"Yollotis Manzur, Nicol├ís Isuani, Alphonso Escobedo\", \"slug\": \"temo-amarte\", \"year\": 2024, \"title\": \"Temo Amarte\", \"poster\": \"\", \"country\": \"M├⌐xico\", \"director\": \"Rodolfo Graziano\", \"duration\": 35, \"synopsis\": \"La pareja perfecta, el ep├¡tome del amor, hasta el decreto final del destino. En el abrazo de la tragedia, el amor revela su credo ensombrecido, y caro, oh tan caro, el precio debe ser redimido.\"}]}, {\"name\": \"Cortometrajes Uruguayos en Competencia\", \"type\": \"shorts\", \"films\": [{\"cast\": \"Jimena Ramos\", \"slug\": \"4-0-la-ultima-pregunta\", \"year\": 2023, \"title\": \"4.0: La ├║ltima pregunta\", \"country\": \"Uruguay\", \"director\": \"Juan Pablo Bornio\", \"duration\": 5, \"synopsis\": \"Una de las ├║ltimas supervivientes de un apocalipsis rob├│tico se encuentra prisionera en uno de los ├║ltimos lugares a los que han llegado los robots. Debe encontrar la forma de romper el sistema del robot para liberarla, haci├⌐ndole una ├║ltima pregunta. Pero debe tener cuidado con las palabras que utiliza.\"}, {\"cast\": \"Pablo Pipolo, Israel Mirenda, Ishaia Mirenda\", \"slug\": \"el-actor-errante\", \"year\": 2023, \"title\": \"El Actor Errante\", \"country\": \"Uruguay\", \"director\": \"Israel Miranda\", \"duration\": 10, \"synopsis\": \"Un actor arrogante recibe el breve gui├│n que debe interpretar. Evidentemente, es menos de lo que esperaba. Hojeando las p├íginas iniciales, el actor empieza a darse cuenta de que no es una obra corriente. Tal vez, sea su propia historia, inmersa en una disparatada comedia.\"}, {\"cast\": \"Jimena Arias, Luc├¡a Blasco, Lucca Vallejos, Kristina Tomic, Mauro Minini, Ignacio Varela\", \"slug\": \"cazando-mariposas\", \"year\": 2024, \"title\": \"Cazando Mariposas\", \"country\": \"Uruguay\", \"director\": \"Ignacio Varela\", \"duration\": 10, \"synopsis\": \"Un grupo de amigos decide esconderse en su colegio por la noche para encontrar lo que se cuenta en los m├¡ticos cuentos, sin saber que son ellos los encontrados.\"}, {\"cast\": \"Esteban Steve P├⌐rez\", \"slug\": \"el-cobrador-fraternal\", \"year\": 2024, \"title\": \"El Cobrador Fraternal\", \"country\": \"Uruguay\", \"director\": \"Esteban Steve P├⌐rez\", \"duration\": 4, \"synopsis\": \"Mezcla de carnicer├¡a brutal y poes├¡a introspectiva, esta historia sigue a un asesino s├ídico pero emp├ítico que intenta escapar de su destino, pero sigue atrapado. Desdibuja las l├¡neas entre el bien y el mal, ofreciendo una nueva visi├│n del hero├¡smo y la venganza, mostrando su lado terap├⌐utico y extra├▒amente altruista.\"}, {\"cast\": \"Camila Giannotti, Maite Bigi, Sebasti├ín Herrera\", \"slug\": \"la-casa-de-abajo\", \"year\": 2024, \"title\": \"La casa de abajo\", \"country\": \"Uruguay\", \"director\": \"Pablo C├⌐sar Silva Peralta\", \"duration\": 15, \"synopsis\": \"El d├¡a de la muerte de su abuela, Ona visita la casa de su infancia. All├¡ encuentra una cinta grabada por su padre, del que recuerda muy poco, ya que padec├¡a una enfermedad mental. Pero al reproducirlo, la grabaci├│n hace aparecer otras voces, aunque proceden de una trampilla situada bajo la cama. Al descender por ella, descubre la misma casa, pero en el pasado. Una casa debajo de la otra en una superposici├│n infinita, cada vez m├ís profunda en el tiempo. Comprendiendo que su ├║nica opci├│n es descender, Ona se convierte en espectadora de los acontecimientos de su propia l├¡nea familiar.\"}, {\"cast\": \"Daly Borges\", \"slug\": \"la-bruja-del-campo\", \"year\": 2024, \"title\": \"La Bruja del Campo\", \"country\": \"Uruguay\", \"director\": \"Sim├│n B. Romero\", \"duration\": 5, \"synopsis\": \"Un ni├▒o y su hermano van a pescar. No saben que la bruja est├í cerca.\"}, {\"cast\": \"Valentina Pereyra, Lucia Blasco, Peri de Alencar, Martina Carriquiry, Cirenne Petronio\", \"slug\": \"la-hora-de-los-pajaros\", \"year\": 2022, \"title\": \"La Hora de los P├íjaros\", \"country\": \"Uruguay\", \"director\": \"Emiliano Umpierrez\", \"duration\": 6, \"synopsis\": \"Despu├⌐s de mucho tiempo sin salir de casa, Valentina se reencontrar├í con sus amigosΓÇª Aunque sea lo ├║ltimo que haga.\"}, {\"cast\": \"Natalia Candia, Santiago Mussetti, Ramiro Firme\", \"slug\": \"matagato\", \"year\": 2023, \"title\": \"Matagato\", \"country\": \"Uruguay\", \"director\": \"Ramiro Firme, Santiago Mussetti\", \"duration\": 5, \"synopsis\": \"Natalia est├í grabando a su hermano Rafa y a su amigo Andr├⌐s mientras cuentan una leyenda urbana local, invocando accidentalmente a su villano: un fantasma vengativo y sediento de sangre.\"}, {\"cast\": \"Kaef Valverde, Sof├¡a Yorado, Ezequiel N├║├▒ez\", \"slug\": \"sonria-barbara\", \"year\": 2023, \"title\": \"┬íSonr├¡a, B├írbara!\", \"country\": \"Uruguay\", \"director\": \"Facundo G├│mez\", \"duration\": 3, \"synopsis\": \"En unos tecnol├│gicamente avanzados a├▒os 40, la corporaci├│n de implantes cibern├⌐ticos ┬½Future Technologies┬╗ quiere hacer una demostraci├│n de su ├║ltimo proceso de colocaci├│n de implantes. Para ello, cuentan con una joven deslumbrante: ┬íB├írbara!\"}, {\"cast\": \"Jimena Ramos, Angeles Vald├⌐s\", \"slug\": \"la-tesis-final\", \"year\": 2023, \"title\": \"La Tesis Final\", \"country\": \"Uruguay\", \"director\": \"Miguel Torena Bogao\", \"duration\": 4, \"synopsis\": \"Daila, una joven estudiante de ingenier├¡a realiza su tesis final de la forma menos ortodoxa de todas, a cu├ínto est├í dispuesto el ser humano para lograr reconocimiento.\"}, {\"cast\": \"Camila Rizzo, Rodrigo Arcos\", \"slug\": \"la-ultima-siesta\", \"year\": 2024, \"title\": \"La ├Ültima Siesta\", \"country\": \"Uruguay\", \"director\": \"Luc├¡a Carmela Mart├¡nez\", \"duration\": 6, \"synopsis\": \"En una tarde de verano, la delgada l├¡nea que separa los sue├▒os de la vigilia