/*!40000 ALTER TABLE `pages_aboutcontent` DISABLE KEYS */;
INSERT INTO `pages_aboutcontent` VALUES (1,'A lo largo de sus ediciones, el festival ha crecido en cantidad de pel├¡culas, sedes y p├║blico.\n\nLas funciones se han realizado en distintas salas y centros culturales de Montevideo, manteniendo un formato que combina programaci├│n diversa con participaci├│n activa del p├║blico.','Montevideo Fant├ístico es el primer festival de cine de g├⌐nero del Uruguay, dedicado al terror, la fantas├¡a y la ciencia ficci├│n.\n\nDesde 2005 trabaja con pel├¡culas nacionales e internacionales, con foco en producciones independientes y ultra independientes que suelen quedar fuera de los circuitos de exhibici├│n tradicionales.','El festival se organiza en competencias por categor├¡as y en cada funci├│n el p├║blico vota las pel├¡culas.\n\nEsa din├ímica define el resultado de cada edici├│n y forma parte central de la experiencia.\n\nLa programaci├│n combina producciones nacionales e internacionales, y funciona como un espacio de circulaci├│n para el cine de g├⌐nero independiente.','2026-04-15 02:11:09.541629');
/*!40000 ALTER TABLE `pages_aboutcontent` ENABLE KEYS */;
UNLOCK TABLES;

