INSERT INTO `works_work` VALUES (1,'La Sombra del P├íramo','Shadow of the Moor','feature','competition_int','world_premiere','Argentina / Espa├▒a',2023,98,'Espa├▒ol','Ingl├⌐s','Valentina R├¡os','','','Una fot├│grafa viaja a los Andes para documentar rituales ancestrales y descubre que la c├ímara capta m├ís de lo visible.','A photographer travels to the Andes to document ancestral rituals and discovers the camera captures more than the visible.','','','2026-04-14 22:36:18.100062',1),(2,'Corpus','','short','short_competition','selected','Uruguay',2024,15,'Espa├▒ol','','Mart├¡n Ferreira','','','Un m├⌐dico forense comienza a recibir mensajes cifrados en los cuerpos que examina.','A forensic doctor starts receiving coded messages in the bodies he examines.','','','2026-04-14 22:36:18.107068',1),(3,'After the Flood','','feature','panorama','latam_premiere','Irlanda / Francia',2023,112,'Ingl├⌐s, Irland├⌐s','Espa├▒ol','Aoife Brennan','','','En una ciudad bajo el agua, los sobrevivientes descubren que algo despert├│ en las profundidades.','In a submerged city, survivors discover something has awakened in the depths.','','','2026-04-14 22:36:18.115291',1),(6,'Altar','Altar','feature','competition_int','selected','Filipinas',2007,90,'Filipino','Espa├▒ol','Rico Mar├¡a Ilarde','Zanjoe Marudo, Nor Domingo, Dimples Romana, Dido De La Paz, Kristalyn Engle','','Pel├¡cula de terror filipino ganadora del festival.','','','','2026-04-14 23:10:32.600952',3),(7,'La Balada de Vlad Tepes','La Balada de Vlad Tepes','feature','competition_nat','world_premiere','Uruguay',2009,90,'Espa├▒ol','','Guzm├ín Vila','Silvio Galizzi, Daniel Guridi, Herardo Tr├ípani','','Largometraje de terror nacional con tem├ítica vamp├¡rica.','','','','2026-04-14 23:10:32.613177',3),(8,'La Granja','La Granja','feature','competition_int','selected','Argentina',2008,88,'Espa├▒ol','','Ernesto Aguilar','Lourdes ├üvalos, Juan Gavaida, Roberto Bobe, Mariana Topatigh, Jorge Porcel (h)','','Terror argentino.','','','','2026-